      "texto": "Nina era um raposa curioso que gostava de observar tudo ao redor. Em uma tarde depois da chuva, ele caminhava pelo terreiro da fazenda levando sino pequeno para mostrar aos amigos. No caminho, percebeu que a cesta estava pesada demais. Primeiro, Nina ficou preocupado, mas respirou fundo e olhou melhor embaixo do telhado. Depois, encontrou a professora Ana, que escutou a história com atenção e decidiu acompanhar a busca. Os dois não correram, porque sabiam que pressa podia atrapalhar. Eles olharam atrás das folhas, perto das pedras e ao lado de uma poça pequena. Então Nina procurou perto das flores. Pouco a pouco, a situação ficou mais clara. O amigo segurou sino pequeno, enquanto Nina organizava o caminho para ninguém se machucar. Quando chegaram ao fim da trilha, a família comemorou a solução com um lanche simples. Antes de voltar, Nina agradeceu, guardou o que precisava e disse que tinha aprendido sobre gentileza.",
