      "texto": "Tico era um jacare curioso que gostava de observar tudo ao redor. Em uma manhã de vento leve, ele caminhava pelo varanda da casa levando balde pequeno para mostrar aos amigos. No caminho, percebeu que a cesta estava pesada demais. Primeiro, Tico ficou preocupado, mas respirou fundo e olhou melhor atrás da caixa. Depois, encontrou a irmã Luiza, que escutou a história com atenção e decidiu acompanhar a busca. Os dois não correram, porque sabiam que pressa podia atrapalhar. Eles olharam atrás das folhas, perto das pedras e ao lado de uma poça pequena. Então Tico amarrou uma fita no galho. Pouco a pouco, a situação ficou mais clara. O amigo segurou balde pequeno, enquanto Tico organizava o caminho para ninguém se machucar. Quando chegaram ao fim da trilha, a turma aprendeu que pequenos gestos protegem os amigos. Antes de voltar, Tico agradeceu, guardou o que precisava e disse que tinha aprendido sobre organização.",
