      "texto": "Bento era um golfinho curioso que gostava de observar tudo ao redor. Em uma manhã de vento leve, ele caminhava pelo trilha do sitio levando caixa de frutas para mostrar aos amigos. No caminho, viu uma planta caída no chão. Primeiro, Bento ficou preocupado, mas respirou fundo e olhou melhor ao lado do banco. Depois, encontrou o avô Chico, que escutou a história com atenção e decidiu acompanhar a busca. Os dois não correram, porque sabiam que pressa podia atrapalhar. Eles olharam atrás das folhas, perto das pedras e ao lado de uma poça pequena. Então Bento chamou ajuda sem gritar. Pouco a pouco, a situação ficou mais clara. O amigo segurou caixa de frutas, enquanto Bento organizava o caminho para ninguém se machucar. Quando chegaram ao fim da trilha, os amigos decidiram voltar ali no dia seguinte. Antes de voltar, Bento agradeceu, guardou o que precisava e disse que tinha aprendido sobre atenção.",
