      "texto": "Nino era um lontra curioso que gostava de observar tudo ao redor. Em uma manhã fresca, ele caminhava pelo jardim da vizinha levando balde pequeno para mostrar aos amigos. No caminho, encontrou um filhote assustado. Primeiro, Nino ficou preocupado, mas respirou fundo e olhou melhor junto da cerca. Depois, encontrou a colega Sofia, que escutou a história com atenção e decidiu acompanhar a busca. Os dois não correram, porque sabiam que pressa podia atrapalhar. Eles olharam atrás das folhas, perto das pedras e ao lado de uma poça pequena. Então Nino separou as folhas maiores. Pouco a pouco, a situação ficou mais clara. O amigo segurou balde pequeno, enquanto Nino organizava o caminho para ninguém se machucar. Quando chegaram ao fim da trilha, os amigos decidiram voltar ali no dia seguinte. Antes de voltar, Nino agradeceu, guardou o que precisava e disse que tinha aprendido sobre organização. No dia seguinte, ele contou a aventura para a turma e ouviu novas ideias dos colegas.",
