      "texto": "Neco era um raposa curioso que gostava de observar tudo ao redor. Em uma tarde ensolarada, ele caminhava pelo entrada da sala levando laco amarelo para mostrar aos amigos. No caminho, viu uma planta caída no chão. Primeiro, Neco ficou preocupado, mas respirou fundo e olhou melhor atrás da caixa. Depois, encontrou a amiga Helena, que escutou a história com atenção e decidiu acompanhar a busca. Os dois não correram, porque sabiam que pressa podia atrapalhar. Eles olharam atrás das folhas, perto das pedras e ao lado de uma poça pequena. Então Neco procurou perto das flores. Pouco a pouco, a situação ficou mais clara. O amigo segurou laco amarelo, enquanto Neco organizava o caminho para ninguém se machucar. Quando chegaram ao fim da trilha, o dia ficou marcado como uma aventura simples e bonita. Antes de voltar, Neco agradeceu, guardou o que precisava e disse que tinha aprendido sobre amizade.",
