      "texto": "Mel era um raposa curioso que gostava de observar tudo ao redor. Em uma tarde nublada, ele caminhava pelo terreiro da fazenda levando pote de sementes para mostrar aos amigos. No caminho, percebeu que o lanche ficou esquecido. Primeiro, Mel ficou preocupado, mas respirou fundo e olhou melhor perto do portao. Depois, encontrou o menino Rafael, que escutou a história com atenção e decidiu acompanhar a busca. Os dois não correram, porque sabiam que pressa podia atrapalhar. Eles olharam atrás das folhas, perto das pedras e ao lado de uma poça pequena. Então Mel esperou a chuva diminuir. Pouco a pouco, a situação ficou mais clara. O amigo segurou pote de sementes, enquanto Mel organizava o caminho para ninguém se machucar. Quando chegaram ao fim da trilha, o caminho ficou seguro para todos passarem. Antes de voltar, Mel agradeceu, guardou o que precisava e disse que tinha aprendido sobre atenção.",
