      "texto": "Bibi era um tamandua curioso que gostava de observar tudo ao redor. Em uma manhã clara, ele caminhava pelo parque pequeno levando pano vermelho para mostrar aos amigos. No caminho, viu que a chuva podia molhar os livros. Primeiro, Bibi ficou preocupado, mas respirou fundo e olhou melhor perto do portao. Depois, encontrou a irmã Luiza, que escutou a história com atenção e decidiu acompanhar a busca. Os dois não correram, porque sabiam que pressa podia atrapalhar. Eles olharam atrás das folhas, perto das pedras e ao lado de uma poça pequena. Então Bibi fez um sinal para os colegas. Pouco a pouco, a situação ficou mais clara. O amigo segurou pano vermelho, enquanto Bibi organizava o caminho para ninguém se machucar. Quando chegaram ao fim da trilha, o dia ficou marcado como uma aventura simples e bonita. Antes de voltar, Bibi agradeceu, guardou o que precisava e disse que tinha aprendido sobre respeito.",
