      "texto": "Luna era um capivara curioso que gostava de observar tudo ao redor. Em uma manhã fresca, ele caminhava pelo beira do riacho levando cestinha azul para mostrar aos amigos. No caminho, encontrou um filhote assustado. Primeiro, Luna ficou preocupado, mas respirou fundo e olhou melhor no canto da varanda. Depois, encontrou o menino Rafael, que escutou a história com atenção e decidiu acompanhar a busca. Os dois não correram, porque sabiam que pressa podia atrapalhar. Eles olharam atrás das folhas, perto das pedras e ao lado de uma poça pequena. Então Luna voltou pelo mesmo caminho. Pouco a pouco, a situação ficou mais clara. O amigo segurou cestinha azul, enquanto Luna organizava o caminho para ninguém se machucar. Quando chegaram ao fim da trilha, o animal voltou feliz para casa antes do anoitecer. Antes de voltar, Luna agradeceu, guardou o que precisava e disse que tinha aprendido sobre coragem. No dia seguinte, ele contou a aventura para a turma e ouviu novas ideias dos colegas.",
