      "texto": "Bela era um raposa curioso que gostava de observar tudo ao redor. Em uma manhã clara, ele caminhava pelo canto do pomar levando cestinha azul para mostrar aos amigos. No caminho, viu que a chuva podia molhar os livros. Primeiro, Bela ficou preocupado, mas respirou fundo e olhou melhor ao lado da árvore. Depois, encontrou o professor Davi, que escutou a história com atenção e decidiu acompanhar a busca. Os dois não correram, porque sabiam que pressa podia atrapalhar. Eles olharam atrás das folhas, perto das pedras e ao lado de uma poça pequena. Então Bela levou tudo para um lugar seguro. Pouco a pouco, a situação ficou mais clara. O amigo segurou cestinha azul, enquanto Bela organizava o caminho para ninguém se machucar. Quando chegaram ao fim da trilha, o problema foi resolvido sem pressa e sem confusão. Antes de voltar, Bela agradeceu, guardou o que precisava e disse que tinha aprendido sobre coragem.",
