      "texto": "Luna era um tamandua curioso que gostava de observar tudo ao redor. Em uma manhã de vento leve, ele caminhava pelo pátio da escola levando lanterna verde para mostrar aos amigos. No caminho, percebeu que algo tinha sumido. Primeiro, Luna ficou preocupado, mas respirou fundo e olhou melhor ao lado da árvore. Depois, encontrou o porteiro João, que escutou a história com atenção e decidiu acompanhar a busca. Os dois não correram, porque sabiam que pressa podia atrapalhar. Eles olharam atrás das folhas, perto das pedras e ao lado de uma poça pequena. Então Luna procurou perto das flores. Pouco a pouco, a situação ficou mais clara. O amigo segurou lanterna verde, enquanto Luna organizava o caminho para ninguém se machucar. Quando chegaram ao fim da trilha, o caminho ficou seguro para todos passarem. Antes de voltar, Luna agradeceu, guardou o que precisava e disse que tinha aprendido sobre gentileza.",
