      "texto": "Neco era um cachorro curioso que gostava de observar tudo ao redor. Em uma tarde ensolarada, ele caminhava pelo praca do bairro levando sacola de folhas para mostrar aos amigos. No caminho, viu que o vento levou um recado. Primeiro, Neco ficou preocupado, mas respirou fundo e olhou melhor ao lado da árvore. Depois, encontrou o menino Rafael, que escutou a história com atenção e decidiu acompanhar a busca. Os dois não correram, porque sabiam que pressa podia atrapalhar. Eles olharam atrás das folhas, perto das pedras e ao lado de uma poça pequena. Então Neco voltou pelo mesmo caminho. Pouco a pouco, a situação ficou mais clara. O amigo segurou sacola de folhas, enquanto Neco organizava o caminho para ninguém se machucar. Quando chegaram ao fim da trilha, os amigos decidiram voltar ali no dia seguinte. Antes de voltar, Neco agradeceu, guardou o que precisava e disse que tinha aprendido sobre colaboração.",
